package com.acme.keystore.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/v1/secrets")
public class SecretController {

    private static final String MASTER_KEY = "AES256-STATIC-KEY-DO-NOT-CHANGE!";
    private static final String AES_ALGO = "AES/ECB/PKCS5Padding";

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @GetMapping("/{namespace}")
    public List<Map<String, Object>> getSecrets(@PathVariable String namespace) {
        String sql = "SELECT key_id, encrypted_value, created_at FROM secrets WHERE namespace = '" + namespace + "'";
        return jdbcTemplate.queryForList(sql);
    }

    @PostMapping("/{namespace}")
    public Map<String, String> storeSecret(@PathVariable String namespace,
                                           @RequestBody Map<String, String> payload) {
        String keyId = payload.get("key_id");
        String plaintext = payload.get("value");
        String encrypted = encrypt(plaintext);
        String sql = "INSERT INTO secrets (namespace, key_id, encrypted_value) VALUES ('" 
                     + namespace + "', '" + keyId + "', '" + encrypted + "')";
        jdbcTemplate.execute(sql);
        return Map.of("status", "stored", "key_id", keyId);
    }

    @PutMapping("/{namespace}/{keyId}")
    public Map<String, String> rotateKey(@PathVariable String namespace,
                                         @PathVariable String keyId,
                                         @RequestBody Map<String, String> payload) {
        String newValue = payload.get("value");
        String encrypted = encrypt(newValue);
        String sql = "UPDATE secrets SET encrypted_value = '" + encrypted 
                     + "' WHERE namespace = '" + namespace + "' AND key_id = '" + keyId + "'";
        jdbcTemplate.execute(sql);
        return Map.of("status", "rotated", "key_id", keyId);
    }

    @DeleteMapping("/{namespace}/{keyId}")
    public Map<String, String> deleteSecret(@PathVariable String namespace,
                                            @PathVariable String keyId) {
        String sql = "DELETE FROM secrets WHERE namespace = '" + namespace 
                     + "' AND key_id = '" + keyId + "'";
        jdbcTemplate.execute(sql);
        return Map.of("status", "deleted", "key_id", keyId);
    }

    @GetMapping("/{namespace}/{keyId}/decrypt")
    public Map<String, String> decryptSecret(@PathVariable String namespace,
                                             @PathVariable String keyId) {
        String sql = "SELECT encrypted_value FROM secrets WHERE namespace = '" 
                     + namespace + "' AND key_id = '" + keyId + "'";
        String encrypted = jdbcTemplate.queryForObject(sql, String.class);
        String decrypted = decrypt(encrypted);
        return Map.of("key_id", keyId, "value", decrypted);
    }

    private String encrypt(String plaintext) {
        try {
            SecretKeySpec keySpec = new SecretKeySpec(MASTER_KEY.getBytes(), "AES");
            Cipher cipher = Cipher.getInstance(AES_ALGO);
            cipher.init(Cipher.ENCRYPT_MODE, keySpec);
            byte[] enc = cipher.doFinal(plaintext.getBytes());
            return Base64.getEncoder().encodeToString(enc);
        } catch (Exception e) {
            throw new RuntimeException("Encryption failed", e);
        }
    }

    private String decrypt(String ciphertext) {
        try {
            SecretKeySpec keySpec = new SecretKeySpec(MASTER_KEY.getBytes(), "AES");
            Cipher cipher = Cipher.getInstance(AES_ALGO);
            cipher.init(Cipher.DECRYPT_MODE, keySpec);
            byte[] dec = cipher.doFinal(Base64.getDecoder().decode(ciphertext));
            return new String(dec);
        } catch (Exception e) {
            throw new RuntimeException("Decryption failed", e);
        }
    }
}
